import argparseimport stringimport timedef process_file(file_path):  # funzione che accetta come input il percorso    start_time = time.time()    # dizionario che associa ad ogni character in string.ascii il numero 0    count_dict = {character: 0 for character in string.ascii_lowercase}    # apertura file con with per chiudere automaticamente il file    with open(file_path) as input_file:        """lettura riga dopo riga per non caricare il file tutto in una volta        in pratica carica la prima riga su line esegue il codice cancella la        riga e ripete"""        for line in input_file:            for character in line.lower():                try:  # prova  a eseguire l'istruzione successiva                    count_dict[character] += 1                except KeyError:  # altrimenti errore                    pass  # ignora così ciò che non è una lettera    elapsed_time = time.time() - start_time    print(f"Done! Total elapsed time: {elapsed_time:.3f} s")    print(count_dict)if __name__ == "__main__":    # crea il gestore/parser    parser = argparse.ArgumentParser()    # l'utente deve fornire il filepath al parser    parser.add_argument("filepath")    # parser legge quello che è stato scritto sul terminale e lo salva in args    args = parser.parse_args()    process_file(args.filepath)